// Formatta i risultati per visualizzazione chiara
const items = $input.all();

// Estrai dati da tutti i branch
const summary = items.find(i => i.json.validation_status);
const questions = items.find(i => i.json.questions);
const refined = items.find(i => i.json.refined_model);

let result = {
  // === REPORT DI VALIDAZIONE ===
  validation_report: {
    status: summary?.json.validation_status || 'UNKNOWN',
    total_issues: summary?.json.total_issues || 0,
    breakdown: {
      entity_overlaps: summary?.json.entity_overlaps || 0,
      requirement_conflicts: summary?.json.requirement_conflicts || 0,
      event_violations: summary?.json.event_violations || 0
    }
  },

  // === DOMANDE DI FOLLOW-UP ===
  follow_up_questions: {
    count: summary?.json.questions_count || 0,
    questions: questions?.json.questions ? JSON.parse(questions.json.questions) : []
  },

  // === MODELLO RAFFINATO ===
  refined_model_available: refined?.json.refined_model ? true : false,
  refined_model: refined?.json.refined_model ? JSON.parse(refined.json.refined_model) : null,

  // === TIMESTAMP ===
  analyzed_at: new Date().toISOString()
};

return [{ json: result }];
